#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-284_Q2."""

from __future__ import annotations

from collections import Counter
from datetime import date
from html.parser import HTMLParser
import csv
import json
from pathlib import Path
import re
from typing import Any


TASK_ID = "CSX-284_Q2"
EVENT_ID = "CSX-284"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_2022_Pakistan_extreme_monsoon_rainfall.json",
    "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json",
    "data/exposure_impact/exposure_impact_004_OpenStreetMap_Overpass_bounded_AOI_slice.json",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self._skip_depth = 0
        self.parts: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"script", "style"}:
            self._skip_depth += 1
            return
        for name, value in attrs:
            if name in {"content", "alt", "title"} and value:
                self.parts.append(value)

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style"} and self._skip_depth:
            self._skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if not self._skip_depth:
            self.parts.append(data)

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def read_json(rel_path: str) -> dict[str, Any]:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def read_report_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig", errors="replace"))
    return parser.text()


def manifest_category_counts() -> dict[str, int]:
    counts: Counter[str] = Counter()
    with (PACKAGE_DIR / "metadata/files.csv").open("r", encoding="utf-8-sig", newline="") as handle:
        for row in csv.DictReader(handle):
            counts[row["data_category"]] += 1
    return dict(sorted(counts.items()))


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def safe_ratio(numerator: float, denominator: float) -> float:
    if denominator == 0:
        raise ValueError("ratio denominator is zero")
    return numerator / denominator


def counted_facilities(overpass: dict[str, Any]) -> dict[str, int]:
    labels = {
        "hospital": "hospitals",
        "school": "schools",
        "police": "police",
        "fire_station": "fire_stations",
        "shelter": "shelters",
    }
    counts: Counter[str] = Counter()
    for element in overpass.get("elements", []):
        amenity = element.get("tags", {}).get("amenity")
        if amenity in labels:
            counts[labels[amenity]] += 1
    result = {label: counts[label] for label in labels.values()}
    result["total"] = sum(result.values())
    return result


def rainfall_midpoint(text: str) -> float:
    if not re.search(r"five\s+to\s+six\s+times", text, flags=re.IGNORECASE):
        raise ValueError("expected rainfall anomaly phrase was not found")
    return (5.0 + 6.0) / 2.0


def round_answer(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def build_ground_truth() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_2022_Pakistan_extreme_monsoon_rainfall.json"
    )
    era5 = read_json("data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json")
    remote = read_json("data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    population = read_json("data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json")
    overpass = read_json("data/exposure_impact/exposure_impact_004_OpenStreetMap_Overpass_bounded_AOI_slice.json")
    report_text = read_report_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html")

    dates = anchor["temporal_" + "window"]
    event_span_days = inclusive_days(dates["start_date"], dates["end_date"])
    event_window = {"start": dates["start_date"], "end": dates["end_date"]}
    precipitation_evidence_window = {"start": chirps["start"], "end": chirps["end"]}
    precip_ratios = {
        "chirps": safe_ratio(
            chirps["stats"]["chirps_event_precip_mm_max"],
            chirps["stats"]["chirps_event_precip_mm_mean"],
        ),
        "gpm_imerg": safe_ratio(
            gpm["stats"]["gpm_event_precip_mm_max"],
            gpm["stats"]["gpm_event_precip_mm_mean"],
        ),
        "era5_land": safe_ratio(
            era5["stats"]["precipitation_sum_mm_max"],
            era5["stats"]["precipitation_sum_mm_mean"],
        ),
    }
    mean_precip_peak_ratio = sum(precip_ratios.values()) / len(precip_ratios)
    precip_ratio_spread = max(precip_ratios.values()) - min(precip_ratios.values())
    surface_change_concentration_ratio = safe_ratio(
        remote["stats"]["alphaearth_1_minus_cosine_max"],
        remote["stats"]["alphaearth_1_minus_cosine_mean"],
    )
    facility_counts = counted_facilities(overpass)
    population_sum = float(population["population_sum"]["population"])
    people_per_counted_facility = safe_ratio(population_sum, facility_counts["total"])
    rain_anomaly_midpoint_x = rainfall_midpoint(report_text)

    answer = {
        "event_span_days": event_span_days,
        "mean_precip_peak_ratio": round_answer(mean_precip_peak_ratio),
        "precip_ratio_spread": round_answer(precip_ratio_spread),
        "surface_change_concentration_ratio": round_answer(surface_change_concentration_ratio),
        "people_per_counted_facility": round(people_per_counted_facility, 1),
        "rain_anomaly_midpoint_x": rain_anomaly_midpoint_x,
    }
    threshold_flags = {
        "long_span_ge_90_days": event_span_days >= 90,
        "mean_precip_peak_ratio_ge_1_50": mean_precip_peak_ratio >= 1.50,
        "precip_ratio_spread_le_0_60": precip_ratio_spread <= 0.60,
        "surface_change_concentration_ratio_ge_10": surface_change_concentration_ratio >= 10,
        "people_per_counted_facility_ge_10000": people_per_counted_facility >= 10000,
        "rain_anomaly_midpoint_x_ge_5": rain_anomaly_midpoint_x >= 5,
    }
    score = sum(1 for passed in threshold_flags.values() if passed)
    class_label = (
        "high_consistency_long_span_monsoon_flood_concentration"
        if score == 6
        else "partial_consistency_monsoon_flood_ledger"
    )
    structured_answer = {
        "answer": answer,
        "evidence_windows": {
            "event_window": event_window,
            "precipitation_evidence_window": precipitation_evidence_window,
        },
        "score": score,
        "class_label": class_label,
    }
    answer_guidance = {
        "ledger_values": answer,
        "score": score,
        "class_label": class_label,
        "units": {
            "event_span_days": "days",
            "people_per_counted_facility": "people/facility",
            "ratios": "unitless",
        },
        "tolerances": {
            "event_span_days": 0,
            "mean_precip_peak_ratio": 0.002,
            "precip_ratio_spread": 0.002,
            "surface_change_concentration_ratio": 0.002,
            "people_per_counted_facility": 0.2,
            "rain_anomaly_midpoint_x": 0,
            "score": 0,
        },
        "label_rule": {
            "high_consistency_long_span_monsoon_flood_concentration": "score == 6",
            "partial_consistency_monsoon_flood_ledger": "score < 6",
        },
        "structured_answer": structured_answer,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "pakistan_monsoon_flood_threshold_score_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": structured_answer,
        "answer_guidance": answer_guidance,
        "key_values": {
            "event": {
                "event_name": event["event_name"],
                "package_id": event["package_id"],
                "scale": event["scale"],
                "span_start": dates["start_date"],
                "span_end": dates["end_date"],
            },
            "precipitation_evidence_window": precipitation_evidence_window,
            "precip_peak_ratios": {key: round_answer(value) for key, value in precip_ratios.items()},
            "precip_mm": {
                "chirps_mean": round_answer(chirps["stats"]["chirps_event_precip_mm_mean"]),
                "chirps_max": round_answer(chirps["stats"]["chirps_event_precip_mm_max"]),
                "gpm_imerg_mean": round_answer(gpm["stats"]["gpm_event_precip_mm_mean"]),
                "gpm_imerg_max": round_answer(gpm["stats"]["gpm_event_precip_mm_max"]),
                "era5_land_mean": round_answer(era5["stats"]["precipitation_sum_mm_mean"]),
                "era5_land_max": round_answer(era5["stats"]["precipitation_sum_mm_max"]),
            },
            "remote_change": {
                "annual_mean": round(remote["stats"]["alphaearth_1_minus_cosine_mean"], 6),
                "annual_max": round_answer(remote["stats"]["alphaearth_1_minus_cosine_max"]),
            },
            "exposure_counts": {
                "population_sum": round(population_sum, 3),
                "facilities": facility_counts,
            },
            "rainfall_text_metric": {
                "phrase_found": "five to six times",
                "midpoint_x": rain_anomaly_midpoint_x,
            },
            "threshold_flags": threshold_flags,
            "manifest_category_counts": manifest_category_counts(),
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "event_span_arithmetic",
                    "points": 4,
                    "description": "Computes the inclusive 110-day span from the locked start and end dates.",
                },
                {
                    "name": "precipitation_ratio_ledger",
                    "points": 4,
                    "description": "Computes the three precipitation evidence-window max/mean ratios, their mean of 1.549, and their spread of 0.445.",
                },
                {
                    "name": "surface_change_ratio",
                    "points": 3,
                    "description": "Computes the annual surface-change concentration ratio of 15.734 from max divided by mean.",
                },
                {
                    "name": "facility_density_denominator",
                    "points": 3,
                    "description": "Counts 1000 relevant amenities and computes 14336.7 people per counted facility.",
                },
                {
                    "name": "rainfall_anomaly_midpoint",
                    "points": 2,
                    "description": "Extracts the five-to-six-times phrase and converts it to a midpoint of 5.5.",
                },
                {
                    "name": "threshold_score_and_json",
                    "points": 4,
                    "description": "Applies the six threshold tests, returns score 6, uses the explicit class-label rule, and supplies the requested compact JSON fields.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    text = json.dumps(build_ground_truth(), indent=2, sort_keys=True, ensure_ascii=True) + "\n"
    OUTPUT_PATH.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    main()
